def project_root() -> Path:
    candidates = [Path.cwd(), Path(__file__).resolve().parent, Path.cwd().parent,
                  Path(__file__).resolve().parent.parent]
    for base in candidates:
        if (base / "src/game/roster.ts").is_file():
            return base.resolve()
    raise RuntimeError("Could not find src/game/roster.ts. Place this installer in your game's web folder and run it there.")


def data_bytes(embedded: str, digest: str, kind: str) -> bytes:
    raw = zlib.decompress(base64.b85decode("".join(embedded.split()).encode("ascii")))
    if hashlib.sha256(raw).hexdigest() != digest:
        raise RuntimeError(f"Embedded {kind} integrity check failed")
    return raw


def verify_vrm(data: bytes) -> None:
    if len(data) < 28:
        raise RuntimeError("Invalid embedded VRM: too small")
    magic, version, length = struct.unpack_from("<III", data)
    if magic != 0x46546C67 or version != 2 or length != len(data):
        raise RuntimeError("Invalid embedded VRM: glTF header mismatch")
    jsonlen, chunk_type = struct.unpack_from("<II", data, 12)
    if chunk_type != 0x4E4F534A:
        raise RuntimeError("Invalid embedded VRM: missing JSON chunk")
    doc = json.loads(data[20:20 + jsonlen])
    if "VRMC_vrm" not in doc.get("extensions", {}):
        raise RuntimeError("Invalid embedded VRM: missing VRM extension")


def roster_patch(current: str) -> tuple[str, str]:
    # Limit the edit to the Zephyr roster entry; never global-replace Garrick.
    pattern = re.compile(r'(\{\s*id\s*:\s*"zephyr"\s*,[\s\S]*?\blook\s*:\s*\{[^}]*?\bvrm\s*:\s*")([^"\n]+)(")')
    matches = list(pattern.finditer(current))
    if len(matches) != 1:
        raise RuntimeError(f"Expected exactly one Zephyr look.vrm roster entry, found {len(matches)}. Source unchanged.")
    match = matches[0]
    old_vrm = match.group(2)
    if old_vrm not in ("garrick", "zephyr"):
        raise RuntimeError(f"Zephyr already has a custom VRM reference ({old_vrm!r}); refusing to overwrite it.")
    updated = current[:match.start(2)] + "zephyr" + current[match.end(2):]
    return updated, old_vrm


def atomic_stage(path: Path, data: bytes) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".zephyr-stage-", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
    except Exception:
        try: os.unlink(temp)
        except OSError: pass
        raise
    return Path(temp)


def main() -> int:
    parser = argparse.ArgumentParser(description="Install optimized Zephyr VRM into Fight Royale")
    parser.add_argument("--dry-run", action="store_true", help="Preflight only; do not change any files")
    parser.add_argument("--replace-icon", action="store_true", help="Replace existing Zephyr character portrait with the included icon")
    args = parser.parse_args()
    root = project_root()
    roster = root / "src/game/roster.ts"
    model_path = root / "public/models/zephyr.vrm"
    icon_path = root / "public/icons/chars/zephyr.webp"

    original_text = roster.read_text(encoding="utf-8-sig")
    updated_text, old_vrm = roster_patch(original_text)
    model = data_bytes(MODEL_DATA_B85, MODEL_SHA256, "VRM")
    icon = data_bytes(ICON_DATA_B85, ICON_SHA256, "icon")
    verify_vrm(model)

    to_write: list[tuple[Path,bytes]] = []
    if updated_text != original_text:
        # Preserve the original UTF-8 BOM if present.
        bom = b"\xef\xbb\xbf" if roster.read_bytes().startswith(b"\xef\xbb\xbf") else b""
        to_write.append((roster, bom + updated_text.encode("utf-8")))
    if not model_path.exists() or hashlib.sha256(model_path.read_bytes()).hexdigest() != MODEL_SHA256:
        to_write.append((model_path, model))
    if args.replace_icon or not icon_path.exists():
        if not icon_path.exists() or hashlib.sha256(icon_path.read_bytes()).hexdigest() != ICON_SHA256:
            to_write.append((icon_path, icon))

    print("ZEPHYR — OPTIMIZED VRM INSTALLER")
    print("Project:", root)
    print("Roster Zephyr VRM:", old_vrm, "=> zephyr")
    print("Optimized VRM:", f"{len(model)/1024/1024:.2f} MiB")
    print("Included portrait:", f"{len(icon)/1024:.0f} KiB")
    for path, data in to_write:
        print("  CHANGE:", path.relative_to(root), f"({len(data):,} bytes)")
    if icon_path.exists() and not args.replace_icon:
        print("  KEEP: public/icons/chars/zephyr.webp (existing custom icon)")

    if not to_write:
        print("Already installed: matching optimized VRM and roster; no changes made.")
        return 0
    if args.dry_run:
        print("DRY RUN OK: all anchors and asset hashes valid. No files modified.")
        return 0

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup_dir = root / "scripts/backups" / f"zephyr_vrm_{timestamp}"
    backups: dict[Path,Path | None] = {}
    staged: dict[Path,Path] = {}
    modified: list[Path] = []
    try:
        backup_dir.mkdir(parents=True,exist_ok=False)
        for dest, payload in to_write:
            if dest.exists():
                # Backup copies do not end in '.ts' to avoid tsconfig auto-including them.
                bak = backup_dir / (dest.name + ".backup")
                shutil.copy2(dest, bak)
                backups[dest] = bak
            else:
                backups[dest] = None
        for dest, payload in to_write:
            staged[dest] = atomic_stage(dest, payload)
        for dest, payload in to_write:
            os.replace(staged[dest], dest)
            modified.append(dest)
        if hashlib.sha256(model_path.read_bytes()).hexdigest() != MODEL_SHA256:
            raise RuntimeError("Post-install VRM hash mismatch")
        check, result = roster_patch(roster.read_text(encoding="utf-8-sig"))
        if result != "zephyr":
            raise RuntimeError("Post-install roster still points to old model")
    except Exception:
        for dest in reversed(modified):
            previous = backups.get(dest)
            if previous is None:
                dest.unlink(missing_ok=True)
            else:
                shutil.copy2(previous,dest)
        print("Installation failed; modified files rolled back.",file=sys.stderr)
        raise
    finally:
        for temp in staged.values():
            temp.unlink(missing_ok=True)
    print("INSTALLED: Zephyr now loads public/models/zephyr.vrm")
    print("Backups:", backup_dir)
    print("Next: npx tsc --noEmit -p .  &&  npm run dev")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:
        print("ERROR:", exc, file=sys.stderr)
        sys.exit(1)
